//! Shared helpers of the integration tests: a throw-away hub on `127.0.0.1:0` with a small cast of users, a raw HTTP
//! helper (what `curl` would do) and a CSV reader that is *not* ours (python's `csv` module).
//!
//! Every token in here is generated by the hub for the test and dies with the temporary directory.
#![allow(dead_code)]

use citro_core::profile::Profile;
use citro_hub::client::{Client, Device};
use citro_hub::model::{TeamRole, UserRole};
use citro_hub::server::admin;
use citro_hub::server::run::Hub;
use citro_hub::server::store::Config;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static COUNTER: AtomicU64 = AtomicU64::new(0);

/// A fresh directory under `$TMPDIR`, removed again when dropped.
pub struct TempDir(PathBuf);

impl TempDir {
    pub fn new(tag: &str) -> TempDir {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_nanos());
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("citro-hub-it-{tag}-{}-{n}-{nanos}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("temp dir");
        TempDir(dir)
    }

    pub fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

pub fn sha256_hex(data: &[u8]) -> String {
    format!("{:x}", Sha256::digest(data))
}

/// Deterministic pseudo-random bytes: a stand-in for a profile archive.
pub fn blob(len: usize, seed: u64) -> Vec<u8> {
    let mut x = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

pub fn test_config() -> Config {
    Config { bind: "127.0.0.1:0".parse().expect("address"), ..Config::default() }
}

pub fn now_secs() -> i64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_secs() as i64)
}

/// A hub with one team (`Acme`) and four users:
///
/// | user  | server role | role in Acme |
/// |-------|-------------|--------------|
/// | anna  | admin       | owner        |
/// | ben   | member      | member       |
/// | cara  | member      | member       |
/// | vera  | member      | viewer       |
pub struct World {
    // Declared first so that it is dropped (= stopped) before the directory goes away.
    pub hub: Option<Hub>,
    pub cfg: Config,
    pub data: PathBuf,
    pub team: String,
    pub anna: String,
    pub ben: String,
    pub cara: String,
    pub vera: String,
    pub tmp: TempDir,
}

impl World {
    pub fn new() -> World {
        World::with(test_config())
    }

    pub fn with(cfg: Config) -> World {
        let tmp = TempDir::new("hub");
        let data = tmp.path().join("hub");
        let anna = admin::create_user(&data, "anna", UserRole::Admin, None).expect("first user").token;
        let ben = admin::create_user(&data, "ben", UserRole::Member, None).expect("ben").token;
        let cara = admin::create_user(&data, "cara", UserRole::Member, None).expect("cara").token;
        let vera = admin::create_user(&data, "vera", UserRole::Member, None).expect("vera").token;
        let (team, _) = admin::create_team(&data, "Acme", Some("anna")).expect("team");
        for (user, role) in [("ben", TeamRole::Member), ("cara", TeamRole::Member), ("vera", TeamRole::Viewer)] {
            admin::add_member(&data, &team.id, user, role).expect("membership");
        }
        let hub = Hub::start(&data, cfg.clone()).expect("the hub starts");
        World { hub: Some(hub), cfg, data, team: team.id, anna, ben, cara, vera, tmp }
    }

    pub fn url(&self) -> String {
        self.hub.as_ref().expect("the hub is running").url()
    }

    /// A client for `token` acting as device `device_id` (its name is derived from the id).
    pub fn client(&self, token: &str, device_id: &str, device_name: &str) -> Client {
        Client::new(&self.url(), token, Device::new(device_id, device_name)).expect("client")
    }

    pub fn anna(&self) -> Client {
        self.client(&self.anna, "dev-anna", "Anna's Mac")
    }

    pub fn ben(&self) -> Client {
        self.client(&self.ben, "dev-ben", "Ben's laptop")
    }

    pub fn cara(&self) -> Client {
        self.client(&self.cara, "dev-cara", "Cara's desktop")
    }

    pub fn vera(&self) -> Client {
        self.client(&self.vera, "dev-vera", "Vera's tablet")
    }

    /// Create a plain profile in Acme (as anna) and return its id.
    pub fn profile(&self, name: &str) -> String {
        let p = Profile { name: name.to_owned(), ..Default::default() };
        self.anna().create_profile(&self.team, &p).expect("create profile").profile.profile_id
    }

    /// Stop the hub (state to disk) and start it again on the same data directory. It gets a new port: clients made
    /// before the restart point to the old one.
    pub fn restart(&mut self) {
        self.hub.take().expect("the hub is running").stop();
        self.hub = Some(Hub::start(&self.data, self.cfg.clone()).expect("the hub restarts"));
    }
}

// ---- raw HTTP -------------------------------------------------------------------------------------------------------

/// What came back over the wire.
pub struct Raw {
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Raw {
    pub fn json(&self) -> Value {
        serde_json::from_slice(&self.body).unwrap_or(Value::Null)
    }

    pub fn text(&self) -> String {
        String::from_utf8_lossy(&self.body).into_owned()
    }

    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers.iter().find(|(k, _)| k.eq_ignore_ascii_case(name)).map(|(_, v)| v.as_str())
    }
}

/// One plain HTTP request, the way `curl` would send it. `token` becomes `Authorization: Bearer ...`.
pub fn raw(method: &str, url: &str, token: Option<&str>, headers: &[(&str, &str)], body: Option<&[u8]>) -> Raw {
    let agent = ureq::Agent::new_with_config(
        ureq::Agent::config_builder().http_status_as_error(false).max_redirects(0).build(),
    );
    let mut rb = ureq::http::Request::builder().method(method).uri(url);
    if let Some(t) = token {
        rb = rb.header("Authorization", format!("Bearer {t}"));
    }
    for (k, v) in headers {
        rb = rb.header(*k, *v);
    }
    let mut resp = match body {
        Some(b) => agent.run(rb.body(b.to_vec()).expect("request")),
        None => agent.run(rb.body(()).expect("request")),
    }
    .expect("the hub answers");
    let headers = resp
        .headers()
        .iter()
        .map(|(k, v)| (k.as_str().to_owned(), String::from_utf8_lossy(v.as_bytes()).into_owned()))
        .collect();
    let status = resp.status().as_u16();
    let body = resp.body_mut().read_to_vec().expect("body");
    Raw { status, headers, body }
}

/// The rows of a CSV file as python's `csv` module (strict mode) sees them: an independent reader.
pub fn python_csv_rows(dir: &Path, bytes: &[u8]) -> Vec<Vec<String>> {
    let path = dir.join(format!("export-{}.csv", COUNTER.fetch_add(1, Ordering::Relaxed)));
    std::fs::write(&path, bytes).expect("write csv");
    let script = "import csv, json, sys\n\
                  with open(sys.argv[1], encoding='utf-8-sig', newline='') as f:\n\
                  \x20   print(json.dumps(list(csv.reader(f, strict=True))))\n";
    let out = Command::new("python3")
        .arg("-I")
        .arg("-c")
        .arg(script)
        .arg(&path)
        .output()
        .expect("python3 must be installed to run this test");
    assert!(out.status.success(), "python could not parse the CSV: {}", String::from_utf8_lossy(&out.stderr));
    serde_json::from_slice(&out.stdout).expect("python printed JSON")
}

// ---- one TCP connection, spoken by hand ---------------------------------------------------------------------------

/// A single keep-alive connection driven byte by byte: a test can send a request in pieces (the body arrives after
/// the head, the way a slow or busy client does), read the answer, and then find out whether the same connection is
/// still good for the next request. A pooled HTTP client does exactly that, and a hub that closes the connection
/// behind a refusal makes it fail with "Peer disconnected" or "Broken pipe" instead of the refusal.
pub struct Wire {
    stream: std::net::TcpStream,
    /// Bytes read from the socket but not consumed by an answer yet.
    pending: Vec<u8>,
}

impl Wire {
    /// `base_url` as `World::url` returns it: `http://127.0.0.1:PORT`.
    pub fn connect(base_url: &str) -> Wire {
        let addr = base_url.trim_start_matches("http://").trim_end_matches('/');
        let stream = std::net::TcpStream::connect(addr).expect("connect to the hub");
        stream.set_nodelay(true).expect("nodelay: each write goes out as its own packet");
        stream.set_read_timeout(Some(std::time::Duration::from_secs(30))).expect("read timeout");
        Wire { stream, pending: Vec::new() }
    }

    pub fn send(&mut self, bytes: &[u8]) {
        use std::io::Write;
        self.stream.write_all(bytes).expect("write to the hub");
        self.stream.flush().expect("flush");
    }

    /// The next answer (interim `100 Continue` answers are skipped), or why there is none.
    pub fn answer(&mut self) -> Result<Raw, String> {
        loop {
            let head_end = loop {
                if let Some(i) = self.pending.windows(4).position(|w| w == b"\r\n\r\n") {
                    break i + 4;
                }
                self.fill()?;
            };
            let head = String::from_utf8_lossy(&self.pending[..head_end - 4]).into_owned();
            let mut lines = head.split("\r\n");
            let status: u16 = lines
                .next()
                .and_then(|l| l.split(' ').nth(1))
                .and_then(|s| s.parse().ok())
                .ok_or_else(|| format!("no status line in {head:?}"))?;
            let headers: Vec<(String, String)> = lines
                .filter_map(|l| l.split_once(':'))
                .map(|(k, v)| (k.trim().to_owned(), v.trim().to_owned()))
                .collect();
            self.pending.drain(..head_end);
            if status == 100 {
                continue;
            }
            let length = headers
                .iter()
                .find(|(k, _)| k.eq_ignore_ascii_case("content-length"))
                .and_then(|(_, v)| v.parse::<usize>().ok())
                .unwrap_or(0);
            while self.pending.len() < length {
                self.fill()?;
            }
            let body = self.pending.drain(..length).collect();
            return Ok(Raw { status, headers, body });
        }
    }

    /// `true` when the hub has closed this connection (nothing more will ever come out of it).
    pub fn is_closed_by_hub(&mut self) -> bool {
        self.stream.set_read_timeout(Some(std::time::Duration::from_secs(5))).expect("read timeout");
        matches!(self.fill(), Err(e) if e.contains("closed"))
    }

    fn fill(&mut self) -> Result<(), String> {
        use std::io::Read;
        let mut chunk = [0u8; 16 * 1024];
        match self.stream.read(&mut chunk) {
            Ok(0) => Err("the hub closed the connection".to_owned()),
            Ok(n) => {
                self.pending.extend_from_slice(&chunk[..n]);
                Ok(())
            }
            Err(e) => Err(format!("the connection broke: {e}")),
        }
    }
}
